// Step 1: Validate Risk Payload
const payload = $input.first().json.body || $input.first().json;

if (!payload) {
  throw new Error('Invalid payload: request body is empty.');
}

const riskForecast = payload.riskForecast || {};
const area = payload.area || { name: 'Adyar Sector Alpha' };
const rawSeverity = String(payload.severity || (payload.riskScore >= 75 ? 'CRITICAL' : payload.riskScore >= 60 ? 'HIGH' : 'MODERATE')).toUpperCase();
const validSeverities = ['CRITICAL', 'HIGH', 'MODERATE', 'LOW'];
const severity = validSeverities.includes(rawSeverity) ? rawSeverity : 'HIGH';

const riskScore = typeof payload.riskScore === 'number' ? payload.riskScore : (severity === 'CRITICAL' ? 85 : severity === 'HIGH' ? 68 : 45);

const commander = payload.commander || {
  name: 'Cmdr Jaswant Karun',
  email: 'jksam37@gmail.com',
  role: 'INCIDENT_COMMANDER'
};

const timestamp = payload.timestamp || new Date().toISOString();
const simulationMode = payload.simulationMode !== undefined ? Boolean(payload.simulationMode) : false;

return [{
  json: {
    riskForecast,
    area,
    severity,
    riskScore,
    commander,
    timestamp,
    simulationMode,
    isValid: true,
    validatedAt: new Date().toISOString()
  }
}];

// Step 2: Check Severity & Formulate Human Review Safeguards
const data = $input.first().json;
const severity = data.severity;
const riskScore = data.riskScore;

const isHighOrCritical = severity === 'HIGH' || severity === 'CRITICAL' || riskScore >= 60;
const isCritical = severity === 'CRITICAL' || riskScore >= 75;

// RESQNET Safety Protocol:
// For CRITICAL alerts: Require commander review before simulated emergency execution.
// The email may notify the commander, but emergency execution still requires human approval.
const requiresCommanderReview = isCritical;
const emergencyExecutionStatus = isCritical ? 'AWAITING_COMMANDER_APPROVAL' : 'NOT_APPLICABLE';

return [{
  json: {
    ...data,
    evaluation: {
      severity,
      riskScore,
      isHighOrCritical,
      isCritical,
      requiresCommanderReview,
      emergencyExecutionStatus,
      humanApprovalPolicy: 'Emergency execution strictly requires human approval before simulated deployment.'
    }
  }
}];

// Step 4: Create Alert Log Entry
const data = $input.first().json;
const alertId = `ALT-RISK-${Date.now().toString(36).toUpperCase()}`;
const areaName = data.area?.name || data.area?.shortName || 'Zone A - Saidapet';

const alertLog = {
  alertId,
  timestamp: data.timestamp,
  loggedAt: new Date().toISOString(),
  areaName,
  severity: data.severity,
  riskScore: data.riskScore,
  hazard: data.riskForecast?.hazardType || 'FLOOD',
  commanderName: data.commander?.name || 'Cmdr Jaswant Karun',
  recipient: data.commander?.email || 'jksam37@gmail.com',
  status: 'PENDING_EMAIL_DISPATCH',
  requiresCommanderReview: data.evaluation.requiresCommanderReview,
  emergencyExecutionStatus: data.evaluation.emergencyExecutionStatus,
  safeguardNotice: 'Human authorization required before simulated emergency execution.'
};

return [{
  json: {
    ...data,
    alertId,
    alertLog
  }
}];

// Step: Low / Moderate Risk - Alert Skipped Log
const data = $input.first().json;
return [{
  json: {
    ...data,
    skipReason: `Severity (${data.severity}) is below alert threshold (HIGH/CRITICAL). No email dispatch necessary.`
  }
}];
